<?php include 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $q=trim($_POST['question']); $o1=trim($_POST['option1']); $o2=trim($_POST['option2']); $o3=trim($_POST['option3']); $ca=(int)$_POST['correct_answer']; if($q==''||$o1==''||$o2==''||$o3==''||$ca<1||$ca>3){$msg='All options and correct answer required';} else {$stmt=mysqli_prepare($conn,'INSERT INTO questions(question,option1,option2,option3,correct_answer) VALUES(?,?,?,?,?)'); mysqli_stmt_bind_param($stmt,'ssssi',$q,$o1,$o2,$o3,$ca); mysqli_stmt_execute($stmt);}}
?> <!DOCTYPE html><html><head><title>Q19 Admin</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Add Quiz Question</h1><a href="index.php">Take Quiz</a><form method="post"><textarea name="question" placeholder="Question"></textarea><input name="option1" placeholder="Option 1"><input name="option2" placeholder="Option 2"><input name="option3" placeholder="Option 3"><select name="correct_answer"><option value="1">Option 1</option><option value="2">Option 2</option><option value="3">Option 3</option></select><button>Add</button></form><p><?php echo $msg; ?></p></div></body></html>
